import click


def test_when_argument_decorator_is_used_multiple_times_cls_is_preserved():
    class CustomArgument(click.Argument):
        pass

    arg = click.argument("arg", cls=CustomArgument)

    @click.command()
    @arg
    def cli(arg):
        pass

    assert isinstance(cli.params[0], CustomArgument)

    @click.command()
    @arg
    def cli(arg):
        pass

    assert isinstance(cli.params[0], CustomArgument)


def test_plain_argument_default_cls():
    @click.command()
    @click.argument("arg")
    def cli(arg):
        pass

    assert type(cli.params[0]) is click.Argument
